function parseConfig(text) {
  // Null-prototype: config text is untrusted input, and a key named
  // `__proto__` or `constructor` must not be able to reach Object.prototype.
  const config = Object.create(null);
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const trimmed = lines[i].trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    // Reject rather than guess: a line without `=` has no defensible reading,
    // and silently mis-splitting it corrupts the key it was meant to set.
    if (eq === -1) {
      throw new Error(`Invalid config on line ${i + 1}: expected key=value, got "${trimmed}"`);
    }
    const key = trimmed.slice(0, eq).trim();
    if (key === '') {
      throw new Error(`Invalid config on line ${i + 1}: empty key`);
    }
    config[key] = trimmed.slice(eq + 1).trim();
  }
  return config;
}

function loadConfig(path) {
  let text;
  try {
    // Read once at startup, before anything is serving: the synchronous call
    // costs nothing that matters here and keeps every caller free of a promise.
    text = fs.readFileSync(path, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`Configuration file not found: ${path}`);
    }
    throw err;
  }
  return parseConfig(text);
}

