const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');

const { parseConfig, loadConfig } = require('../src/config');

test('parses key=value pairs', () => {
  const config = parseConfig('name=world\ngreeting=hi');
  assert.strictEqual(config.name, 'world');
  assert.strictEqual(config.greeting, 'hi');
});

test('skips blank lines and comments', () => {
  const config = parseConfig('# a comment\n\n   \nname=world\n');
  assert.deepStrictEqual(Object.keys(config), ['name']);
});

test('trims whitespace around keys and values', () => {
  const config = parseConfig('  name  =  world  ');
  assert.strictEqual(config.name, 'world');
});

test('handles CRLF line endings', () => {
  const config = parseConfig('name=world\r\n');
  assert.strictEqual(config.name, 'world');
});

test('handles a missing trailing newline', () => {
  const config = parseConfig('name=world');
  assert.strictEqual(config.name, 'world');
});

test('keeps = characters inside the value', () => {
  const config = parseConfig('token=a=b=c');
  assert.strictEqual(config.token, 'a=b=c');
});

test('last duplicate key wins', () => {
  const config = parseConfig('name=a\nname=b');
  assert.strictEqual(config.name, 'b');
});

test('rejects a line with no =', () => {
  assert.throws(() => parseConfig('name=world\nDEBUG'), /line 2.*DEBUG/);
});

test('rejects an empty key', () => {
  assert.throws(() => parseConfig('=orphan'), /empty key/);
});

test('does not expose Object.prototype members', () => {
  const config = parseConfig('name=world');
  assert.strictEqual(config.constructor, undefined);
  assert.strictEqual(config.toString, undefined);
});

test('a __proto__ key does not reach Object.prototype', () => {
  const config = parseConfig('__proto__=pwned');
  assert.strictEqual(config.__proto__, 'pwned');
  assert.strictEqual({}.pwned, undefined);
});

test('loadConfig reads a file from disk', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'config-test-'));
  const file = path.join(dir, 'app.conf');
  fs.writeFileSync(file, '# hello\nname=from-disk\n');
  try {
    assert.strictEqual(loadConfig(file).name, 'from-disk');
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test('loadConfig reports a missing file by path', () => {
  const missing = path.join(os.tmpdir(), 'definitely-absent-app.conf');
  assert.throws(() => loadConfig(missing), /Configuration file not found.*definitely-absent-app\.conf/);
});

